from contextlib import contextmanager
from contextvars import ContextVar

_current_tenant: ContextVar = ContextVar("current_tenant", default=None)


def get_current_tenant():
    return _current_tenant.get()


@contextmanager
def tenant_context(tenant):
    token = _current_tenant.set(tenant)
    try:
        yield tenant
    finally:
        _current_tenant.reset(token)

from django.http import HttpResponseNotFound

from .context import tenant_context
from .models import Tenant


class TenantMiddleware:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        subdomain = request.get_host().split(":")[0].split(".")[0]
        try:
            tenant = Tenant.objects.get(slug=subdomain, is_active=True)
        except Tenant.DoesNotExist:
            return HttpResponseNotFound("Unknown tenant")
        request.tenant = tenant
        with tenant_context(tenant):
            return self.get_response(request)

slug = request.headers.get("X-Tenant")
tenant = Tenant.objects.filter(slug=slug, is_active=True).first()
if tenant is None or not request.user.memberships.filter(tenant=tenant).exists():
    return JsonResponse({"detail": "Forbidden"}, status=403)

class TenantManager(models.Manager):
    def get_queryset(self):
        qs = super().get_queryset()
        tenant = get_current_tenant()
        if tenant is None:
            return qs.none()
        return qs.filter(tenant=tenant)

class TenantModel(models.Model):
    tenant = models.ForeignKey("tenancy.Tenant", on_delete=models.CASCADE, editable=False)

    objects = TenantManager()          # scoped, used by default
    unscoped = models.Manager()        # deliberate escape hatch (admin, commands, tests)

    class Meta:
        abstract = True

    def save(self, *args, **kwargs):
        if self.tenant_id is None:
            tenant = get_current_tenant()
            if tenant is None:
                raise RuntimeError("Saving a tenant model without a current tenant")
            self.tenant = tenant
        super().save(*args, **kwargs)

class Invoice(TenantModel):
    number = models.CharField(max_length=30)

    class Meta:
        constraints = [
            models.UniqueConstraint(fields=["tenant", "number"], name="uniq_invoice_number_per_tenant"),
        ]

@shared_task
def recalc_totals(tenant_id):
    tenant = Tenant.objects.get(pk=tenant_id)
    with tenant_context(tenant):
        for invoice in Invoice.objects.all():
            invoice.recalculate()

# enqueue:  recalc_totals.delay(request.tenant.pk)

def tenant_upload_to(instance, filename):
    return f"tenants/{instance.tenant_id}/{filename}"

class Document(TenantModel):
    file = models.FileField(upload_to=tenant_upload_to)

class TenantAdmin(admin.ModelAdmin):
    def get_queryset(self, request):
        qs = self.model.unscoped.all()
        if request.user.is_superuser:
            return qs
        return qs.filter(tenant=request.tenant)

